// A failure's backtrace (TODO §29), made when the machine stops at it:
// the procedures whose activations its continuation holds, innermost
// first, from the call it failed in (`node`, in `env`; -1 if none is
// known) out. A frame's node says its lambda (`node-owner`), and its
// environment its activation: one activation's frames have environments
// each an ancestor of the one before, where two calls' of one procedure
// have neither. A proper tail call leaves no frame, so its caller is not
// there, as in any machine that has tail calls. Consecutive activations of
// one procedure are one line, with their count; what is outside every
// lambda, none.
pub enum Activation {
    Activation(i64, i64, i64),
}

pub fn activation(f0: i64, f1: i64, f2: i64) -> &'static Activation {
    kayak_rt::heap_alloc(Activation::Activation(f0, f1, f2))
}

pub fn frame_node(k: i64) -> i64 {
    let kind = frame_kind(k);
    if (i64_eq(kind, fk_if()) || i64_eq(kind, fk_seq()) || i64_eq(kind, fk_list()) || i64_eq(kind, fk_letrec()) || i64_eq(kind, fk_tagcase()) || i64_eq(kind, fk_ptag())) {
        code_index(frame_field(k, 0i64))
    } else if i64_eq(kind, fk_phandler()) {
        code_index(frame_field(k, 1i64))
    } else {
        -1i64
    }
}

pub fn frame_env(k: i64) -> i64 {
    let kind = frame_kind(k);
    if (i64_eq(kind, fk_if()) || i64_eq(kind, fk_tagcase()) || i64_eq(kind, fk_ptag())) {
        frame_field(k, 1i64)
    } else if (i64_eq(kind, fk_seq()) || i64_eq(kind, fk_list()) || i64_eq(kind, fk_letrec()) || i64_eq(kind, fk_phandler())) {
        frame_field(k, 2i64)
    } else {
        0i64
    }
}

/// Whether `outer` is `e` or one of its parents.
pub fn env_within_p(mut outer: i64, mut e: i64, mut depth: i64) -> bool {
    loop {
        if i64_eq(e, outer) {
            return true;
        } else if (i64_gt(depth, 256i64) || not(pointer_p(e)) || not(is_obj_p(e, ob_env()))) {
            return false;
        } else {
            (e, depth) = (obj_ref(e, 0i64), i64_plus(depth, 1i64));
            continue;
        }
    }
}

// The walk out along the frames, a loop however deep the continuation:
// the activation it is in (`owner`, -1 none yet; `env`), how many of that
// lambda's have come one after another (`n`), and the runs finished, the
// first 17 kept (last first), and how many.
pub enum Walked {
    Walked(List<&'static Activation>, i64),
}

pub fn walked(f0: List<&'static Activation>, f1: i64) -> &'static Walked {
    kayak_rt::heap_alloc(Walked::Walked(f0, f1))
}

pub fn activations(mut owner: i64, mut env: i64, mut n: i64, mut k: i64, mut acc: List<&'static Activation>, mut runs: i64) -> &'static Walked {
    loop {
        if i64_eq(k, w_nil()) {
            if i64_lt(owner, 0i64) {
                return walked(acc, runs);
            } else {
                return walked(kayak_rt::heap_cons(activation(owner, env, n), acc), i64_plus(runs, 1i64));
            }
        } else {
            let nd = frame_node(k);
            let o = node_owner(nd);
            let e = frame_env(k);
            let next = frame_next(k);
            if i64_lt(nd, 0i64) {
                k = next;
                continue;
            } else if i64_lt(owner, 0i64) {
                (owner, env, n, k) = (o, e, 1i64, next);
                continue;
            } else if (i64_eq(o, owner) && env_within_p(e, env, 0i64)) {
                (env, k) = (e, next);
                continue;
            } else if i64_eq(o, owner) {
                (env, n, k) = (e, i64_plus(n, 1i64), next);
                continue;
            } else {
                (owner, env, n, k, acc, runs) = (o, e, 1i64, next, if i64_lt(runs, 17i64) {
                    kayak_rt::heap_cons(activation(owner, env, n), acc)
                } else {
                    acc
                }, i64_plus(runs, 1i64));
                continue;
            }
        }
    }
}

pub fn activations_reversed(mut xs: List<&'static Activation>, mut acc: List<&'static Activation>) -> List<&'static Activation> {
    loop {
        if null_p(xs) {
            return acc;
        } else {
            (xs, acc) = (cdr(xs), kayak_rt::heap_cons(car(xs), acc));
            continue;
        }
    }
}

pub fn trace_lines(xs: List<&'static Activation>, shown: i64, runs: i64) -> List<Str> {
    if null_p(xs) {
        nil::<Str>()
    } else if i64_gt_eq(shown, 16i64) {
        kayak_rt::heap_cons(string_append(str_lit("... and "), string_append(i64_to_string(i64_minus(runs, 16i64)), str_lit(" more"))), kayak_rt::nil())
    } else {
        let tagcase_ = car(xs);
        match *tagcase_ {
            Activation::Activation(o, e, n) => {
                kayak_rt::heap_cons(string_append(str_lit("in "), string_append(array_ref(get(wheres()), i64_to_int(o)), if i64_gt(n, 1i64) {
                    string_append(str_lit(", "), string_append(i64_to_string(n), str_lit(" calls")))
                } else {
                    str_lit("")
                })), trace_lines(cdr(xs), i64_plus(shown, 1i64), runs))
            }
        }
    }
}

/// The machine stopped at a failure: its backtrace kept, if none is
/// yet; `w-failed`.
pub fn stopped_x(node: i64, env: i64, k: i64) -> i64 {
    if null_p(get(engine_trace())) {
        let tagcase_ = activations(node_owner(node), env, 1i64, k, nil::<&'static Activation>(), 0i64);
        match *tagcase_ {
            Walked::Walked(acc, runs) => {
                set(engine_trace(), trace_lines(activations_reversed(acc, nil::<&'static Activation>()), 0i64, runs))
            }
        }
    } else {
        ()
    };
    w_failed()
}

// Steps until the next slice's end, as Fixpt's machine counts them
// (`sched::SLICE`), at which the scheduler may preempt the current task.
pub fn sched_slice() -> i64 {
    65536i64
}

pub fn sched_poll() -> Ref<i64> {
    kayak_rt::kept_constant!(ONCE: Ref<i64>);
    once(&ONCE, || {
        kayak_rt::heap_new(65536i64)
    })
}

/// A step: at a slice's end, the scheduler's `preempt`, if it would have
/// another task run (Fixpt's `preempt_due`), the task then quiet until it
/// has returned; else `#f`.
pub fn preempt_at_x(k: i64) -> i64 {
    if i64_gt(get(sched_poll()), 1i64) {
        set(sched_poll(), i64_minus(get(sched_poll()), 1i64));
        w_false()
    } else {
        set(sched_poll(), sched_slice());
        if not(sched_p()) {
            w_false()
        } else {
            let (f, t) = (sched_ref(s_preempt()), sched_ref(s_tag()));
            if (is_obj_p(f, ob_proc()) && wanted_x((not(i64_eq(t, w_false())) && i64_gt_eq(frames_to(k, tag_number(t), 0i64), 0i64)))) {
                quiet_enter_x();
                f
            } else {
                w_false()
            }
        }
    }
}

pub fn run(mut mode: i64, mut node: i64, mut env: i64, mut k: i64, mut val: i64, mut f: i64, mut args: i64) -> i64 {
    loop {
        if get(engine_failed()) {
            return failed_at(if i64_eq(mode, 0i64) {
                node
            } else {
                -1i64
            }, env, k);
        } else if i64_lt(heap_room(), reserve()) {
            return gc_run(mode, node, env, k, val, f, args, 0i64);
        } else {
            if i64_eq(get(fuel()), 0i64) {
                return park_x(mode, node, env, k, val, f, args);
            } else if (i64_gt_eq(get(deadline()), 0i64) && past_deadline_p()) {
                return park_x(mode, node, env, k, val, f, args);
            } else if (i64_eq(mode, 0i64) && not(i64_eq(preempt_at_x(k), w_false()))) {
                (mode, node, env, k, val, f, args) = (2i64, -1i64, 0i64, frame_x(fk_preempted(), k, 2i64, code_word(node), env, 0i64, 0i64), 0i64, sched_ref(s_preempt()), w_nil());
                continue;
            } else if i64_eq(mode, 0i64) {
                if i64_gt(get(fuel()), 0i64) {
                    set(fuel(), i64_minus(get(fuel()), 1i64))
                } else {
                    ()
                };
                let tagcase_ = node_at(node);
                match *tagcase_ {
                    Node::NLit(c) => {
                        (mode, node, val, f, args) = (1i64, 0i64, constant_at(c), 0i64, 0i64);
                        continue;
                    }
                    Node::NLocal(d, s) => {
                        (mode, node, val, f, args) = (1i64, 0i64, obj_ref(env_up(env, d), i64_plus(s, 1i64)), 0i64, 0i64);
                        continue;
                    }
                    Node::NGlobal(i) => {
                        let w = flatarray_ref_i64(get(globals()), i);
                        if i64_eq(w, w_unbound()) {
                            unbound_global(i);
                            return failed_at(node, env, k);
                        } else {
                            (mode, node, val, f, args) = (1i64, 0i64, w, 0i64, 0i64);
                            continue;
                        }
                    }
                    Node::NLambda(n, body) => {
                        let p = alloc_x(ob_proc(), 2i64);
                        obj_set_x(p, 0i64, code_word(node));
                        obj_set_x(p, 1i64, env);
                        (mode, node, val, f, args) = (1i64, 0i64, p, 0i64, 0i64);
                        continue;
                    }
                    Node::NCall(at, count) => {
                        (mode, node, k, val, f, args) = (0i64, kid_at(at), frame_x(fk_list(), k, 4i64, code_word(node), fixnum(1i64), env, w_nil()), 0i64, 0i64, 0i64);
                        continue;
                    }
                    Node::NIf(c, t, e) => {
                        (mode, node, k, val, f, args) = (0i64, c, frame_x(fk_if(), k, 2i64, code_word(node), env, 0i64, 0i64), 0i64, 0i64, 0i64);
                        continue;
                    }
                    Node::NSeq(at, count) => {
                        if i64_eq(count, 0i64) {
                            (mode, node, val, f, args) = (1i64, 0i64, w_unit(), 0i64, 0i64);
                            continue;
                        } else if i64_eq(count, 1i64) {
                            (mode, node, val, f, args) = (0i64, kid_at(at), 0i64, 0i64, 0i64);
                            continue;
                        } else {
                            (mode, node, k, val, f, args) = (0i64, kid_at(at), frame_x(fk_seq(), k, 3i64, code_word(node), fixnum(1i64), env, 0i64), 0i64, 0i64, 0i64);
                            continue;
                        }
                    }
                    Node::NLet(at, count, body) => {
                        if i64_eq(count, 0i64) {
                            let e = alloc_x(ob_env(), 1i64);
                            obj_set_x(e, 0i64, env);
                            (mode, node, env, val, f, args) = (0i64, body, e, 0i64, 0i64, 0i64);
                            continue;
                        } else {
                            (mode, node, k, val, f, args) = (0i64, kid_at(at), frame_x(fk_list(), k, 4i64, code_word(node), fixnum(1i64), env, w_nil()), 0i64, 0i64, 0i64);
                            continue;
                        }
                    }
                    Node::NLetrec(at, count, body) => {
                        let e = alloc_x(ob_env(), i64_plus(count, 1i64));
                        obj_set_x(e, 0i64, env);
                        fill_unbound_x(e, 1i64, count);
                        if i64_eq(count, 0i64) {
                            (mode, node, env, val, f, args) = (0i64, body, e, 0i64, 0i64, 0i64);
                            continue;
                        } else {
                            (mode, node, env, k, val, f, args) = (0i64, kid_at(at), e, frame_x(fk_letrec(), k, 3i64, code_word(node), fixnum(0i64), e, 0i64), 0i64, 0i64, 0i64);
                            continue;
                        }
                    }
                    Node::NDefine(i, x) => {
                        (mode, node, k, val, f, args) = (0i64, x, frame_x(fk_define(), k, 1i64, fixnum(i), 0i64, 0i64, 0i64), 0i64, 0i64, 0i64);
                        continue;
                    }
                    Node::NSum(t, x) => {
                        (mode, node, k, val, f, args) = (0i64, x, frame_x(fk_sum(), k, 1i64, fixnum(t), 0i64, 0i64, 0i64), 0i64, 0i64, 0i64);
                        continue;
                    }
                    Node::NProduct(labels, at, count) => {
                        if i64_eq(count, 0i64) {
                            let p = alloc_x(ob_product(), 1i64);
                            obj_set_x(p, 0i64, fixnum(labels));
                            (mode, node, val, f, args) = (1i64, 0i64, p, 0i64, 0i64);
                            continue;
                        } else {
                            (mode, node, k, val, f, args) = (0i64, kid_at(at), frame_x(fk_list(), k, 4i64, code_word(node), fixnum(1i64), env, w_nil()), 0i64, 0i64, 0i64);
                            continue;
                        }
                    }
                    Node::NExtract(l, x) => {
                        (mode, node, k, val, f, args) = (0i64, x, frame_x(fk_extract(), k, 1i64, fixnum(l), 0i64, 0i64, 0i64), 0i64, 0i64, 0i64);
                        continue;
                    }
                    Node::NTagcase(x, start, count, default) => {
                        (mode, node, k, val, f, args) = (0i64, x, frame_x(fk_tagcase(), k, 2i64, code_word(node), env, 0i64, 0i64), 0i64, 0i64, 0i64);
                        continue;
                    }
                    Node::NPrompt(t, h, body) => {
                        (mode, node, k, val, f, args) = (0i64, t, frame_x(fk_ptag(), k, 2i64, code_word(node), env, 0i64, 0i64), 0i64, 0i64, 0i64);
                        continue;
                    }
                }
            } else if i64_eq(mode, 1i64) {
                if i64_eq(k, w_nil()) {
                    return val;
                } else {
                    let (kind, next) = (frame_kind(k), frame_next(k));
                    if i64_eq(kind, fk_if()) {
                        let tagcase_ = node_at(code_index(frame_field(k, 0i64)));
                        match *tagcase_ {
                            Node::NIf(c, t, e) => {
                                (mode, node, env, k, val, f, args) = (0i64, if truthy_p(val) {
                                    t
                                } else {
                                    e
                                }, frame_field(k, 1i64), next, 0i64, 0i64, 0i64);
                                continue;
                            }
                            _ => {
                                let other = tagcase_;
                                (mode, node, k, f, args) = (1i64, 0i64, next, 0i64, 0i64);
                                continue;
                            }
                        }
                    } else if i64_eq(kind, fk_seq()) {
                        let tagcase_ = node_at(code_index(frame_field(k, 0i64)));
                        match *tagcase_ {
                            Node::NSeq(at, count) => {
                                let (pos, e) = (fixnum_value(frame_field(k, 1i64)), frame_field(k, 2i64));
                                if i64_eq(i64_plus(pos, 1i64), count) {
                                    (mode, node, env, k, val, f, args) = (0i64, kid_at(i64_plus(at, pos)), e, next, 0i64, 0i64, 0i64);
                                    continue;
                                } else {
                                    (mode, node, env, k, val, f, args) = (0i64, kid_at(i64_plus(at, pos)), e, frame_x(fk_seq(), next, 3i64, frame_field(k, 0i64), fixnum(i64_plus(pos, 1i64)), e, 0i64), 0i64, 0i64, 0i64);
                                    continue;
                                }
                            }
                            _ => {
                                let other = tagcase_;
                                (mode, node, k, f, args) = (1i64, 0i64, next, 0i64, 0i64);
                                continue;
                            }
                        }
                    } else if i64_eq(kind, fk_list()) {
                        return list_step(k, next, val);
                    } else if i64_eq(kind, fk_letrec()) {
                        let e = frame_field(k, 2i64);
                        let pos = fixnum_value(frame_field(k, 1i64));
                        obj_set_x(e, i64_plus(pos, 1i64), val);
                        let tagcase_ = node_at(code_index(frame_field(k, 0i64)));
                        match *tagcase_ {
                            Node::NLetrec(at, count, body) => {
                                if i64_eq(i64_plus(pos, 1i64), count) {
                                    (mode, node, env, k, val, f, args) = (0i64, body, e, next, 0i64, 0i64, 0i64);
                                    continue;
                                } else {
                                    (mode, node, env, k, val, f, args) = (0i64, kid_at(i64_plus(at, i64_plus(pos, 1i64))), e, frame_x(fk_letrec(), next, 3i64, frame_field(k, 0i64), fixnum(i64_plus(pos, 1i64)), e, 0i64), 0i64, 0i64, 0i64);
                                    continue;
                                }
                            }
                            _ => {
                                let other = tagcase_;
                                (mode, node, k, f, args) = (1i64, 0i64, next, 0i64, 0i64);
                                continue;
                            }
                        }
                    } else if i64_eq(kind, fk_define()) {
                        flatarray_set_i64_x(get(globals()), fixnum_value(frame_field(k, 0i64)), val);
                        (mode, node, k, val, f, args) = (1i64, 0i64, next, w_unit(), 0i64, 0i64);
                        continue;
                    } else if i64_eq(kind, fk_sum()) {
                        let p = alloc_x(ob_sum(), 2i64);
                        obj_set_x(p, 0i64, frame_field(k, 0i64));
                        obj_set_x(p, 1i64, val);
                        (mode, node, k, val, f, args) = (1i64, 0i64, next, p, 0i64, 0i64);
                        continue;
                    } else if i64_eq(kind, fk_extract()) {
                        let i = label_position(fixnum_value(obj_ref(val, 0i64)), i64_minus(obj_size(val), 1i64), fixnum_value(frame_field(k, 0i64)), 0i64);
                        if i64_lt(i, 0i64) {
                            failed_with_x(str_lit("the engine: extract of a field the product has not"));
                            return failed_at(-1i64, 0i64, k);
                        } else {
                            (mode, node, k, val, f, args) = (1i64, 0i64, next, obj_ref(val, i64_plus(i, 1i64)), 0i64, 0i64);
                            continue;
                        }
                    } else if i64_eq(kind, fk_tagcase()) {
                        return tagcase_step(k, next, val);
                    } else if i64_eq(kind, fk_ptag()) {
                        let tagcase_ = node_at(code_index(frame_field(k, 0i64)));
                        match *tagcase_ {
                            Node::NPrompt(t, h, body) => {
                                (mode, node, env, k, val, f, args) = (0i64, h, frame_field(k, 1i64), frame_x(fk_phandler(), next, 3i64, val, frame_field(k, 0i64), frame_field(k, 1i64), 0i64), 0i64, 0i64, 0i64);
                                continue;
                            }
                            _ => {
                                let other = tagcase_;
                                (mode, node, k, f, args) = (1i64, 0i64, next, 0i64, 0i64);
                                continue;
                            }
                        }
                    } else if i64_eq(kind, fk_phandler()) {
                        let tagcase_ = node_at(code_index(frame_field(k, 1i64)));
                        match *tagcase_ {
                            Node::NPrompt(t, h, body) => {
                                (mode, node, env, k, val, f, args) = (0i64, body, frame_field(k, 2i64), frame_x(fk_prompt(), next, 2i64, fixnum(tag_number(frame_field(k, 0i64))), val, 0i64, 0i64), 0i64, 0i64, 0i64);
                                continue;
                            }
                            _ => {
                                let other = tagcase_;
                                (mode, node, k, f, args) = (1i64, 0i64, next, 0i64, 0i64);
                                continue;
                            }
                        }
                    } else if i64_eq(kind, fk_prompt()) {
                        (mode, node, k, f, args) = (1i64, 0i64, next, 0i64, 0i64);
                        continue;
                    } else if i64_eq(kind, fk_mark()) {
                        (mode, node, k, f, args) = (1i64, 0i64, next, 0i64, 0i64);
                        continue;
                    } else if i64_eq(kind, fk_preempted()) {
                        quiet_leave_x();
                        (mode, node, env, k, val, f, args) = (0i64, code_index(frame_field(k, 0i64)), frame_field(k, 1i64), next, 0i64, 0i64, 0i64);
                        continue;
                    } else if i64_eq(kind, fk_abort()) {
                        return abort_to(fixnum_value(frame_field(k, 0i64)), next, val);
                    } else {
                        failed_with_x(str_lit("the engine: a frame of no kind"));
                        return failed_at(-1i64, 0i64, k);
                    }
                }
            } else {
                return apply_step(node, env, f, args, k);
            }
        }
    }
}

/// The registers kept in the task's slot of the roots; `w-paused`.
pub fn park_x(mode: i64, node: i64, env: i64, k: i64, val: i64, f: i64, args: i64) -> i64 {
    let (r, at) = (get(roots()), parked_at(get(task_slot())));
    flatarray_set_i64_x(r, at, fixnum(mode));
    flatarray_set_i64_x(r, i64_plus(at, 1i64), fixnum(node));
    flatarray_set_i64_x(r, i64_plus(at, 2i64), env);
    flatarray_set_i64_x(r, i64_plus(at, 3i64), k);
    flatarray_set_i64_x(r, i64_plus(at, 4i64), val);
    flatarray_set_i64_x(r, i64_plus(at, 5i64), f);
    flatarray_set_i64_x(r, i64_plus(at, 6i64), args);
    w_paused()
}

/// The registers to the roots, the heap collected (made room for `need`
/// more), and the step begun again from the roots.
pub fn gc_run(mode: i64, node: i64, env: i64, k: i64, val: i64, f: i64, args: i64, need: i64) -> i64 {
    let r = get(roots());
    flatarray_set_i64_x(r, 0i64, env);
    flatarray_set_i64_x(r, 1i64, k);
    flatarray_set_i64_x(r, 2i64, val);
    flatarray_set_i64_x(r, 3i64, f);
    flatarray_set_i64_x(r, 4i64, args);
    collect_x(r, get(globals()), consts(), i64_plus(need, reserve()));
    run(mode, node, flatarray_ref_i64(r, 0i64), flatarray_ref_i64(r, 1i64), flatarray_ref_i64(r, 2i64), flatarray_ref_i64(r, 3i64), flatarray_ref_i64(r, 4i64))
}

/// A value of a call's, a `let`'s or a product's parts: the next part, or
/// all of them, in order, applied, bound or made a product.
pub fn list_step(k: i64, next: i64, val: i64) -> i64 {
    let nd = code_index(frame_field(k, 0i64));
    let pos = fixnum_value(frame_field(k, 1i64));
    let env = frame_field(k, 2i64);
    let got = pair_x(val, frame_field(k, 3i64));
    let tagcase_ = node_at(nd);
    match *tagcase_ {
        Node::NCall(at, count) => {
            if i64_lt(pos, count) {
                run(0i64, kid_at(i64_plus(at, pos)), env, frame_x(fk_list(), next, 4i64, frame_field(k, 0i64), fixnum(i64_plus(pos, 1i64)), env, got), 0i64, 0i64, 0i64)
            } else {
                let xs = reverse_words_x(got, w_nil());
                run(2i64, nd, env, next, 0i64, pair_car(xs), pair_cdr(xs))
            }
        }
        Node::NLet(at, count, body) => {
            if i64_lt(pos, count) {
                run(0i64, kid_at(i64_plus(at, pos)), env, frame_x(fk_list(), next, 4i64, frame_field(k, 0i64), fixnum(i64_plus(pos, 1i64)), env, got), 0i64, 0i64, 0i64)
            } else {
                let e = alloc_x(ob_env(), i64_plus(count, 1i64));
                obj_set_x(e, 0i64, env);
                fill_from_reversed_x(e, count, got);
                run(0i64, body, e, next, 0i64, 0i64, 0i64)
            }
        }
        Node::NProduct(labels, at, count) => {
            if i64_lt(pos, count) {
                run(0i64, kid_at(i64_plus(at, pos)), env, frame_x(fk_list(), next, 4i64, frame_field(k, 0i64), fixnum(i64_plus(pos, 1i64)), env, got), 0i64, 0i64, 0i64)
            } else {
                let p = alloc_x(ob_product(), i64_plus(count, 1i64));
                obj_set_x(p, 0i64, fixnum(labels));
                fill_from_reversed_x(p, count, got);
                run(1i64, 0i64, env, next, p, 0i64, 0i64)
            }
        }
        _ => {
            let other = tagcase_;
            failed_with_x(str_lit("the engine: a list frame of no list"));
            failed_at(-1i64, 0i64, k)
        }
    }
}

pub fn tagcase_step(k: i64, next: i64, val: i64) -> i64 {
    let tagcase_ = node_at(code_index(frame_field(k, 0i64)));
    match *tagcase_ {
        Node::NTagcase(x, start, count, default) => {
            let env = frame_field(k, 1i64);
            let is_sum = is_obj_p(val, ob_sum());
            let tag = if (is_sum || is_obj_p(val, ob_data())) {
                fixnum_value(obj_ref(val, 0i64))
            } else {
                the::<i64>(-1i64)
            };
            let found = arm_found(start, count, tag);
            if i64_lt(found, 0i64) {
                let e = alloc_x(ob_env(), 2i64);
                obj_set_x(e, 0i64, env);
                obj_set_x(e, 1i64, val);
                run(0i64, default, e, next, 0i64, 0i64, 0i64)
            } else {
                let tagcase_ = armx_at(found);
                match *tagcase_ {
                    Armx::Armx(t, binds, body) => {
                        let whole = if is_sum {
                            obj_ref(val, 1i64)
                        } else {
                            val
                        };
                        if (i64_eq(binds, -1i64) || (is_sum && not(is_obj_p(whole, ob_product())))) {
                            let e = alloc_x(ob_env(), 2i64);
                            obj_set_x(e, 0i64, env);
                            obj_set_x(e, 1i64, whole);
                            run(0i64, body, e, next, 0i64, 0i64, 0i64)
                        } else {
                            let n = i64_minus(obj_size(whole), 1i64);
                            let e = alloc_x(ob_env(), i64_plus(n, 1i64));
                            slots_copied_x(e, whole, 1i64, i64_plus(n, 1i64));
                            obj_set_x(e, 0i64, env);
                            run(0i64, body, e, next, 0i64, 0i64, 0i64)
                        }
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            failed_with_x(str_lit("the engine: a tagcase frame of no tagcase"));
            failed_at(-1i64, 0i64, k)
        }
    }
}

/// A failure: in a task of a monitored group, with the scheduler's
/// prompt on the stack, an abort to it, the failure forgotten and kept
/// for the scheduler (Fixpt's `task_failed`, C219); else the machine
/// stopped.
pub fn failed_at(node: i64, env: i64, k: i64) -> i64 {
    let tag = sched_tag();
    if (i64_eq(tag, w_false()) || i64_lt(frames_to(k, tag_number(tag), 0i64), 0i64)) {
        stopped_x(node, env, k)
    } else {
        let t = task_failed_x(string_word_x(get(engine_failure())), true);
        if i64_eq(t, w_false()) {
            stopped_x(node, env, k)
        } else {
            failure_taken_x();
            abort_to(tag_number(t), k, w_unit())
        }
    }
}

/// To the prompt of `tag`, its handler given `v`.
pub fn abort_to(tag: i64, k: i64, v: i64) -> i64 {
    let n = frames_to(k, tag, 0i64);
    if i64_lt(n, 0i64) {
        failed_with_x(str_lit("the engine: no prompt for the tag"));
        stopped_x(-1i64, 0i64, k)
    } else {
        let p = frame_after(k, n);
        run(2i64, -1i64, 0i64, frame_next(p), 0i64, frame_field(p, 1i64), pair_x(v, w_nil()))
    }
}

/// `f` applied to `args`, at the call `node` in `env` (-1: none known),
/// which a failure's backtrace starts at.
pub fn apply_step(node: i64, env: i64, f: i64, args: i64, k: i64) -> i64 {
    if is_obj_p(f, ob_proc()) {
        let tagcase_ = node_at(code_index(obj_ref(f, 0i64)));
        match *tagcase_ {
            Node::NLambda(arity, body) => {
                if i64_eq(arity, -1i64) {
                    let e = alloc_x(ob_env(), 2i64);
                    obj_set_x(e, 0i64, obj_ref(f, 1i64));
                    obj_set_x(e, 1i64, args);
                    run(0i64, body, e, k, 0i64, 0i64, 0i64)
                } else {
                    let n = list_count(args, 0i64);
                    let e = alloc_x(ob_env(), i64_plus(n, 1i64));
                    obj_set_x(e, 0i64, obj_ref(f, 1i64));
                    args_env_x(e, 1i64, args, n);
                    run(0i64, body, e, k, 0i64, 0i64, 0i64)
                }
            }
            _ => {
                let other = tagcase_;
                failed_with_x(str_lit("the engine: a procedure of no lambda"));
                failed_at(node, env, k)
            }
        }
    } else if is_obj_p(f, ob_ctor()) {
        let n = list_count(args, 0i64);
        let p = alloc_x(ob_data(), i64_plus(n, 1i64));
        obj_set_x(p, 0i64, obj_ref(f, 0i64));
        args_env_x(p, 1i64, args, n);
        run(1i64, 0i64, 0i64, k, p, 0i64, 0i64)
    } else if is_obj_p(f, ob_cont()) {
        let top = obj_ref(f, 0i64);
        let n = fixnum_value(obj_ref(f, 1i64));
        let room = if i64_lt(n, 0i64) {
            the::<i64>(0i64)
        } else {
            frames_room(top, n, 0i64)
        };
        if i64_lt(n, 0i64) {
            // A whole continuation (`cwcc`): the frames are never changed,
            // so the run goes on at them, the current ones dropped.
            run(1i64, 0i64, 0i64, top, pair_car(args), 0i64, 0i64)
        } else if i64_lt(heap_room(), i64_plus(room, reserve())) {
            gc_run(2i64, 0i64, 0i64, k, 0i64, f, args, room)
        } else if (truthy_p(obj_ref(f, 3i64)) && truthy_p(obj_ref(f, 2i64))) {
            failed_with_x(if i64_eq(obj_ref(f, 3i64), fixnum(2i64)) {
                str_lit("a one-shot continuation resumed twice")
            } else {
                str_lit("a continuation resumed twice")
            });
            failed_at(node, env, k)
        } else {
            obj_set_x(f, 2i64, w_true());
            run(1i64, 0i64, 0i64, frames_copied_x(top, n, k), pair_car(args), 0i64, 0i64)
        }
    } else if is_imm_p(f, imm_prim()) {
        let op = immediate_value(f);
        if i64_eq(op, op_make_tag()) {
            let t = get(tags_made());
            set(tags_made(), i64_plus(t, 1i64));
            run(1i64, 0i64, 0i64, k, immediate(imm_tag(), t), 0i64, 0i64)
        } else if i64_eq(op, op_with_mark()) {
            // The thunk called with the mark on the continuation: in place of
            // one of the key there, in tail position, as Scheme's.
            let key = pair_car(args);
            let v = pair_car(pair_cdr(args));
            let thunk = pair_car(pair_cdr(pair_cdr(args)));
            let k2 = if (not(i64_eq(k, w_nil())) && i64_eq(frame_kind(k), fk_mark()) && i64_eq(frame_field(k, 0i64), key)) {
                frame_x(fk_mark(), frame_next(k), 2i64, key, v, 0i64, 0i64)
            } else {
                frame_x(fk_mark(), k, 2i64, key, v, 0i64, 0i64)
            };
            run(2i64, -1i64, 0i64, k2, 0i64, thunk, w_nil())
        } else if i64_eq(op, op_first_mark()) {
            run(1i64, 0i64, 0i64, k, first_mark_in(k, pair_car(args), pair_car(pair_cdr(args))), 0i64, 0i64)
        } else if i64_eq(op, op_current_marks()) {
            let need = i64_star(6i64, i64_plus(marks_count(k, pair_car(args), -1i64, 0i64), 1i64));
            if i64_lt(heap_room(), i64_plus(need, reserve())) {
                gc_run(2i64, 0i64, 0i64, k, 0i64, f, args, need)
            } else {
                run(1i64, 0i64, 0i64, k, marks_in(k, pair_car(args), -1i64, w_nil()), 0i64, 0i64)
            }
        } else if i64_eq(op, op_marks_of()) {
            let c = pair_car(args);
            let key = pair_car(pair_cdr(args));
            let need = i64_star(6i64, i64_plus(marks_count(obj_ref(c, 0i64), key, fixnum_value(obj_ref(c, 1i64)), 0i64), 1i64));
            if i64_lt(heap_room(), i64_plus(need, reserve())) {
                gc_run(2i64, 0i64, 0i64, k, 0i64, f, args, need)
            } else {
                run(1i64, 0i64, 0i64, k, marks_in(obj_ref(c, 0i64), key, fixnum_value(obj_ref(c, 1i64)), w_nil()), 0i64, 0i64)
            }
        } else if i64_eq(op, op_apply()) {
            // `(apply f xs)` (C71): `f` on `xs`'s elements, the list copied, as
            // FX-26 copies it (a fresh list, which a `vlambda` may keep).
            let xs = pair_car(pair_cdr(args));
            let n = proper_count(xs, xs, 0i64);
            let need = i64_star(3i64, i64_plus(n, 1i64));
            if i64_lt(n, 0i64) {
                // A list made cyclic, or improper: Fixpt's failure (C220).
                failed_with_x(str_lit("expected a list"));
                failed_at(node, env, k)
            } else if i64_lt(heap_room(), i64_plus(need, reserve())) {
                gc_run(2i64, 0i64, 0i64, k, 0i64, f, args, need)
            } else {
                run(2i64, -1i64, 0i64, k, 0i64, pair_car(args), reverse_words_x(reverse_words_x(xs, w_nil()), w_nil()))
            }
        } else if i64_eq(op, op_abort()) {
            abort_to(tag_number(pair_car(args)), k, pair_car(pair_cdr(args)))
        } else if (i64_eq(op, op_capture()) || i64_eq(op, op_capture_once())) {
            // A one-shot continuation is captured as a composable one, marked
            // (field 3, 2) so that a second resume fails, as Fixpt's (C219).
            let tag = tag_number(pair_car(pair_cdr(args)));
            let n = frames_to(k, tag, 0i64);
            if i64_lt(n, 0i64) {
                failed_with_x(str_lit("the engine: no prompt for the tag"));
                failed_at(node, env, k)
            } else {
                let c = alloc_x(ob_cont(), 4i64);
                obj_set_x(c, 0i64, k);
                obj_set_x(c, 1i64, fixnum(n));
                obj_set_x(c, 2i64, w_false());
                obj_set_x(c, 3i64, if i64_eq(op, op_capture_once()) {
                    fixnum(2i64)
                } else {
                    w_false()
                });
                run(2i64, -1i64, 0i64, k, 0i64, pair_car(args), pair_x(c, w_nil()))
            }
        } else if i64_eq(op, op_cwcc()) {
            // `(cwcc f)` (C220): `f` given the whole continuation, every
            // frame (`n` -1), to be resumed any number of times.
            let c = alloc_x(ob_cont(), 4i64);
            obj_set_x(c, 0i64, k);
            obj_set_x(c, 1i64, fixnum(-1i64));
            obj_set_x(c, 2i64, w_false());
            obj_set_x(c, 3i64, w_false());
            run(2i64, -1i64, 0i64, k, 0i64, pair_car(args), pair_x(c, w_nil()))
        } else if i64_eq(op, op_suspend()) {
            let tag = tag_number(pair_car(args));
            let n = frames_to(k, tag, 0i64);
            if i64_lt(n, 0i64) {
                failed_with_x(str_lit("the engine: no prompt for the tag"));
                failed_at(node, env, k)
            } else {
                let c = alloc_x(ob_cont(), 4i64);
                obj_set_x(c, 0i64, k);
                obj_set_x(c, 1i64, fixnum(n));
                obj_set_x(c, 2i64, w_false());
                obj_set_x(c, 3i64, w_true());
                run(2i64, -1i64, 0i64, frame_x(fk_abort(), k, 1i64, fixnum(tag), 0i64, 0i64, 0i64), 0i64, pair_car(pair_cdr(args)), pair_x(c, w_nil()))
            }
        } else {
            let need = op_need(op, args);
            if i64_lt(heap_room(), i64_plus(need, reserve())) {
                gc_run(2i64, 0i64, 0i64, k, 0i64, f, args, need)
            } else {
                let v = apply_op(op, args);
                if get(engine_failed()) {
                    failed_at(node, env, k)
                } else {
                    run(1i64, 0i64, 0i64, k, v, 0i64, 0i64)
                }
            }
        }
    } else {
        failed_with_x(str_lit("the engine: a call of no procedure"));
        failed_at(node, env, k)
    }
}

/// A paused run of the task in `slot` run on, until it ends or pauses.
pub fn resume(slot: i64) -> i64 {
    let (r, at) = (get(roots()), parked_at(slot));
    run(fixnum_value(flatarray_ref_i64(r, at)), fixnum_value(flatarray_ref_i64(r, i64_plus(at, 1i64))), flatarray_ref_i64(r, i64_plus(at, 2i64)), flatarray_ref_i64(r, i64_plus(at, 3i64)), flatarray_ref_i64(r, i64_plus(at, 4i64)), flatarray_ref_i64(r, i64_plus(at, 5i64)), flatarray_ref_i64(r, i64_plus(at, 6i64)))
}

pub fn roots_copied_x(mut from: FlatArray<i64>, mut to: FlatArray<i64>, mut i: i64, mut n: i64) -> () {
    loop {
        if i64_gt_eq(i, n) {
            return ();
        } else {
            flatarray_set_i64_x(to, i, flatarray_ref_i64(from, i));
            i = i64_plus(i, 1i64);
            continue;
        }
    }
}

/// The roots long enough for `slot`'s registers.
pub fn roots_room_x(slot: i64) -> () {
    let (old, need) = (get(roots()), parked_at(i64_plus(slot, 1i64)));
    if i64_lt_eq(need, flatarray_length_i64(old)) {
        ()
    } else {
        let bigger = the::<FlatArray<i64>>(make_flatarray_i64(i64_star(need, 2i64), 0i64));
        roots_copied_x(old, bigger, 0i64, flatarray_length_i64(old));
        set(roots(), bigger)
    }
}

/// The task in `slot` made to begin evaluating `node`, a top-level form:
/// as if paused before its first step.
pub fn start_parked_x(slot: i64, node: i64) -> () {
    roots_room_x(slot);
    let (r, at) = (get(roots()), parked_at(slot));
    flatarray_set_i64_x(r, at, fixnum(0i64));
    flatarray_set_i64_x(r, i64_plus(at, 1i64), fixnum(node));
    flatarray_set_i64_x(r, i64_plus(at, 2i64), 0i64);
    flatarray_set_i64_x(r, i64_plus(at, 3i64), w_nil());
    flatarray_set_i64_x(r, i64_plus(at, 4i64), 0i64);
    flatarray_set_i64_x(r, i64_plus(at, 5i64), 0i64);
    flatarray_set_i64_x(r, i64_plus(at, 6i64), w_nil())
}

